sp_widget.client_script:
api.controller = function($scope) {

  var c = this;

  c.getCurrentTrainerId = function() {
    var params = new URLSearchParams(window.location.search);
    return (params.get('trainer') || '');
  };

  c.currentTrainerId = c.getCurrentTrainerId();
  c.showNotificationsPopover = false;

  c.toggleNotifications = function($event) {
    if ($event) $event.stopPropagation();
    c.showNotificationsPopover = !c.showNotificationsPopover;
  };

  c.dismissNotif = function(index) {
    if (c.data.notifications && c.data.notifications.length > index) {
      c.data.notifications.splice(index, 1);
      c.data.unreadCount = c.data.notifications.length;
    }
  };

  c.clearAllNotifications = function() {
    c.data.notifications = [];
    c.data.unreadCount = 0;
  };

  c.refresh = function() {
    c.server.update();
  };

  c.openPage = function(pageId) {
    if (!pageId) return;
    var trainerId = c.getCurrentTrainerId();
    var url = '?id=' + encodeURIComponent(pageId);
    if (trainerId) {
      url += '&trainer=' + encodeURIComponent(trainerId);
    }
    window.location.href = url;
  };

  document.addEventListener('click', function(e) {
    var popover = document.getElementById('trainerNotifPopover');
    var bell = document.getElementById('trainerNotifBell');
    if (popover && bell && !popover.contains(e.target) && !bell.contains(e.target)) {
      $scope.$apply(function() {
        c.showNotificationsPopover = false;
      });
    }
  });

};

sp_widget.css:
/* =========================================================
   CAMPUS360 TRAINER DASHBOARD
   SAME BODY / CONTENT DESIGN
   UPDATED FULL-SCREEN SHELL
   DARK PURPLE SIDEBAR
   ========================================================= */


/* =========================================================
   GLOBAL BOX SIZING
   ========================================================= */

.campus360-trainer-app,
.campus360-trainer-app * {
  box-sizing: border-box;
  font-family: Arial, Helvetica, sans-serif;
}


/* =========================================================
   SERVICE NOW OUTER CHROME
   REMOVE:
   - SERVICENOW TOP HEADER
   - SYSTEM ADMINISTRATOR
   - OUTER PORTAL NAVBAR
   ========================================================= */

body:has(.campus360-trainer-app) {
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  max-width: 100% !important;
  overflow: hidden !important;
}


/*
 * ServiceNow / Service Portal header selectors.
 * These are intentionally outside the Campus360 app.
 */

body:has(.campus360-trainer-app) > .navbar,
body:has(.campus360-trainer-app) .navbar.navbar-inverse,
body:has(.campus360-trainer-app) .sp-navbar,
body:has(.campus360-trainer-app) .sp-navbar-top,
body:has(.campus360-trainer-app) #sp-nav-bar,
body:has(.campus360-trainer-app) #sp-navbar,
body:has(.campus360-trainer-app) #sp-nav-header,
body:has(.campus360-trainer-app) .portal-navbar,
body:has(.campus360-trainer-app) .sp-header,
body:has(.campus360-trainer-app) .sp-top-bar {

  display: none !important;

}


/* =========================================================
   SERVICE NOW WRAPPERS
   ========================================================= */

body:has(.campus360-trainer-app) .container,
body:has(.campus360-trainer-app) .container-fluid,
body:has(.campus360-trainer-app) .row,
body:has(.campus360-trainer-app) [class*="col-"],
body:has(.campus360-trainer-app) .well,
body:has(.campus360-trainer-app) .panel,
body:has(.campus360-trainer-app) .panel-body {

  width: 100% !important;

  max-width: none !important;

  min-width: 0 !important;

  margin-left: 0 !important;
  margin-right: 0 !important;

  padding-left: 0 !important;
  padding-right: 0 !important;

  border: 0 !important;

  box-shadow: none !important;

  background: transparent !important;

}


/* =========================================================
   CAMPUS360 APPLICATION SHELL
   IMPORTANT FIX:
   START DIRECTLY AT VIEWPORT TOP
   ========================================================= */

.campus360-trainer-app {

  position: fixed !important;

  top: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  left: 0 !important;

  width: 100vw !important;

  height: 100vh !important;

  min-width: 100vw !important;
  max-width: 100vw !important;

  min-height: 100vh !important;
  max-height: 100vh !important;

  margin: 0 !important;
  padding: 0 !important;

  display: flex;

  overflow: hidden !important;

  z-index: 99999 !important;

  background: #f4f7fb;

  color: #172a33;

  font-size: 15px;

}


/* =========================================================
   SIDEBAR
   DARK PURPLE - SAME STYLE AS STUDENT PAGES
   ========================================================= */

.campus360-trainer-sidebar {

  position: fixed !important;

  left: 0 !important;
  top: 0 !important;
  bottom: 0 !important;

  width: 250px !important;

  min-width: 250px !important;
  max-width: 250px !important;

  height: 100vh !important;
  min-height: 100vh !important;

  z-index: 100000 !important;

  display: flex;

  flex-direction: column;

  background:
    linear-gradient(
      180deg,
      #130d2f 0%,
      #160d38 48%,
      #100a29 100%
    ) !important;

  border-right: 1px solid #2d2157 !important;

  box-shadow:
    4px 0 18px rgba(10, 7, 30, 0.20);

  overflow: hidden;

}


/* =========================================================
   BRAND
   ========================================================= */

.trainer-brand {

  height: 76px;

  min-height: 76px;

  padding: 0 22px;

  display: flex;

  align-items: center;

  gap: 11px;

  border-bottom: 1px solid #2d2157 !important;

  background:
    linear-gradient(
      135deg,
      #170e38,
      #1c1045
    ) !important;

}


.trainer-brand-mark {

  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  border-radius: 10px;

  display: flex;

  align-items: center;

  justify-content: center;

  background:
    linear-gradient(
      135deg,
      #7c3aed,
      #8b3ff2
    ) !important;

  color: #ffffff;

  font-size: 18px;

  font-weight: 800;

  box-shadow:
    0 6px 15px rgba(124,58,237,.25);

}


.trainer-brand-text strong {

  display: block;

  color: #ffffff !important;

  font-size: 17px;

  font-weight: 800;

}


.trainer-brand-text span {

  display: block;

  margin-top: 2px;

  color: #b9abd8 !important;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 1px;

}


/* =========================================================
   TRAINER PROFILE
   ========================================================= */

.trainer-profile-mini {

  margin: 16px 14px 8px;

  padding: 12px;

  display: flex;

  align-items: center;

  gap: 10px;

  border-radius: 11px;

  background:
    linear-gradient(
      135deg,
      #211342,
      #29164f
    ) !important;

  border: 1px solid #4b3475 !important;

  text-decoration: none !important;

}


.trainer-profile-mini:hover {

  background:
    linear-gradient(
      135deg,
      #29174f,
      #321d5d
    ) !important;

  border-color: #60458e !important;

  text-decoration: none !important;

}


.trainer-avatar,
.trainer-top-avatar,
.student-table-avatar,
.followup-icon,
.coordination-icon,
.trainer-nav-icon {

  display: flex;

  align-items: center;

  justify-content: center;

}


.trainer-avatar,
.trainer-top-avatar,
.student-table-avatar {

  background:
    linear-gradient(
      135deg,
      #7c3aed,
      #8b3ff2
    ) !important;

  color: #ffffff;

  font-weight: 800;

}


.trainer-avatar {

  width: 38px;
  height: 38px;

  flex: 0 0 38px;

  border-radius: 10px;

  font-size: 12px;

}


.trainer-profile-info {

  min-width: 0;

  flex: 1;

}


.trainer-profile-info strong {

  display: block;

  color: #ffffff !important;

  font-size: 12px;

  font-weight: 900;

  white-space: nowrap;

  overflow: hidden;

  text-overflow: ellipsis;

}


.trainer-profile-info span {

  display: block;

  margin-top: 3px;

  color: #b9abd8 !important;

  font-size: 10px;

  font-weight: 700;

}


.trainer-profile-arrow {

  color: #a99bc7 !important;

  font-size: 16px;

}


/* =========================================================
   NAVIGATION
   ========================================================= */

.trainer-nav {

  padding: 7px 10px 25px;

  overflow-y: auto;

  overflow-x: hidden;

  flex: 1;

  scrollbar-width: none !important;

  -ms-overflow-style: none !important;

}


.trainer-nav::-webkit-scrollbar {

  width: 0 !important;
  height: 0 !important;

}


.trainer-nav::-webkit-scrollbar-track {

  background: transparent !important;

}


.trainer-nav::-webkit-scrollbar-thumb {

  background: transparent !important;

  border-radius: 10px;

}


.trainer-nav-label {

  margin: 18px 10px 7px;

  color: #9283b6 !important;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 1.2px;

}


.trainer-nav-item {

  min-height: 43px;

  margin: 2px 0;

  padding: 0 11px;

  display: flex;

  align-items: center;

  gap: 10px;

  border-radius: 9px;

  color: #c4b8dc !important;

  text-decoration: none !important;

  font-size: 12px;

  font-weight: 800;

  transition:
    background .18s ease,
    color .18s ease,
    transform .18s ease;

}


.trainer-nav-item:hover {

  background:
    rgba(124,58,237,.18) !important;

  color: #ffffff !important;

  transform: translateX(1px);

}


.trainer-nav-item.active {

  background:
    linear-gradient(
      90deg,
      #7c3aed 0%,
      #8b3ff2 100%
    ) !important;

  color: #ffffff !important;

  border-left: 4px solid #a78bfa !important;

  padding-left: 7px;

  box-shadow:
    inset 0 0 0 1px rgba(196,181,253,.10),
    0 6px 16px rgba(124,58,237,.16);

}


.trainer-nav-icon {

  width: 23px;

  min-width: 23px;

  text-align: center;

  color: #a99ac8 !important;

  font-size: 17px;

}


.trainer-nav-item:hover
.trainer-nav-icon {

  color: #ffffff !important;

}


.trainer-nav-item.active
.trainer-nav-icon {

  color: #ffffff !important;

}


.trainer-nav-count {

  min-width: 21px;

  height: 21px;

  margin-left: auto;

  padding: 0 6px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 20px;

  background: #3a2764 !important;

  color: #d9ceef !important;

  font-size: 10px;

  font-weight: 900;

}


.trainer-nav-item.active
.trainer-nav-count {

  background: rgba(255,255,255,.18) !important;

  color: #ffffff !important;

}


.trainer-nav-count.warning {

  background: #5a3511 !important;

  color: #ffd08a !important;

}


/* =========================================================
   MAIN
   IMPORTANT FIX:
   USE ALL SPACE BESIDE SIDEBAR
   ========================================================= */

.campus360-trainer-main {

  position: absolute !important;

  left: 250px !important;

  top: 0 !important;

  right: 0 !important;

  bottom: 0 !important;

  width: calc(100vw - 250px) !important;

  max-width: calc(100vw - 250px) !important;

  min-width: 0 !important;

  height: 100vh !important;

  min-height: 100vh !important;

  margin: 0 !important;

  padding: 0 !important;

  overflow-x: hidden !important;

  overflow-y: auto !important;

  background: #f4f7fb;

}


/* =========================================================
   TOP NAVBAR
   SAME DASHBOARD LOOK
   ========================================================= */

.trainer-topbar {

  position: sticky;

  top: 0;

  z-index: 5000;

  width: 100%;

  height: 68px;

  min-height: 68px;

  padding: 0 30px;

  display: flex;

  justify-content: space-between;

  align-items: center;

  background: #ffffff;

  border-bottom: 1px solid #e2e8ef;

}


.trainer-topbar-left {

  min-width: 0;

  display: flex;

  align-items: center;

  gap: 12px;

}


.trainer-page-heading {

  min-width: 0;

  display: flex;

  flex-direction: column;

}


.trainer-topbar-eyebrow {

  display: block;

  color: #673cff;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 1.4px;

}


.trainer-topbar-title {

  display: block;

  margin-top: 3px;

  color: #172a33;

  font-size: 16px;

  font-weight: 800;

}


.trainer-topbar-actions {

  display: flex;

  align-items: center;

  gap: 9px;

}


.trainer-top-icon {

  position: relative;

  width: 38px;

  height: 38px;

  flex: 0 0 38px;

  border-radius: 10px;

  border: 1px solid #dfe6ee;

  background: #ffffff;

  color: #536476;

  display: flex;

  align-items: center;

  justify-content: center;

  text-decoration: none !important;

  cursor: pointer;

  transition:
    color .18s ease,
    background .18s ease,
    border-color .18s ease;

}


.trainer-top-icon:hover {

  color: #673cff;

  border-color: #c9baff;

  background: #f8f5ff;

}


.trainer-notification-button {

  overflow: visible;

}


.trainer-top-icon .fa-bell {

  color: #f39c12;

  font-size: 18px;

}


.top-notification-dot {

  position: absolute;

  width: 8px;

  height: 8px;

  border-radius: 50%;

  background: #e74c3c;

  top: 7px;

  right: 7px;

  border: 2px solid #ffffff;

}


.trainer-top-profile {

  display: flex;

  align-items: center;

  gap: 9px;

  text-decoration: none !important;

}


.trainer-top-avatar {

  width: 35px;

  height: 35px;

  flex: 0 0 35px;

  border-radius: 9px;

  font-size: 11px;

}


.trainer-top-profile strong {

  display: block;

  color: #263b49;

  font-size: 11px;

  font-weight: 900;

}


.trainer-top-profile span {

  display: block;

  margin-top: 2px;

  color: #66788a;

  font-size: 10px;

  font-weight: 700;

}


/* =========================================================
   EVERYTHING BELOW HERE IS YOUR EXISTING BODY STYLING
   KEPT UNCHANGED
   ========================================================= */

.trainer-dashboard-content {

  width: 100%;

  padding: 28px 30px 55px;

}


/* ==================== WELCOME ==================== */

.trainer-welcome {

  display: flex;

  justify-content: space-between;

  align-items: center;

  gap: 20px;

  margin-bottom: 24px;

}


.trainer-eyebrow,
.trainer-panel-heading > div > span,
.ai-card-top > div > span,
.coordination-copy > span {

  display: block;

  color: #673cff;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 1.7px;

}


.trainer-welcome h1 {

  margin: 0;

  color: #172a33;

  font-size: 29px;

  line-height: 1.2;

  font-weight: 800;

}


.trainer-welcome p {

  margin: 8px 0 0;

  color: #65768a;

  font-size: 14px;

  line-height: 1.5;

}


.trainer-id-card {

  min-width: 130px;

  padding: 13px 17px;

  border-radius: 11px;

  background: #ffffff;

  border: 1px solid #dcd2ff;

  box-shadow: 0 4px 15px rgba(31, 45, 61, 0.04);

}


/* TRAINER NOTIFICATION POPOVER STYLES */

.student-notif-popover {
    position: absolute;
    top: 45px;
    right: 0;
    width: 360px;
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 12px;
    box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.15), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
    z-index: 1050;
    overflow: hidden;
    font-family: inherit;
    animation: fadeInPopover 0.2s ease-in-out;
    text-align: left;
}

@keyframes fadeInPopover {
    from { opacity: 0; transform: translateY(-8px); }
    to { opacity: 1; transform: translateY(0); }
}

.snotif-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    background: #f9fafb;
    border-bottom: 1px solid #e5e7eb;
}

.snotif-title {
    font-size: 13px;
    font-weight: 700;
    color: #111827;
    display: flex;
    align-items: center;
    gap: 8px;
}

.snotif-count-pill {
    background: #fee2e2;
    color: #dc2626;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border-radius: 12px;
}

.snotif-clear-all {
    background: none;
    border: none;
    color: #6b7280;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
}

.snotif-clear-all:hover {
    color: #ef4444;
}

.snotif-body {
    max-height: 320px;
    overflow-y: auto;
    padding: 8px;
}

.snotif-empty {
    text-align: center;
    padding: 20px 12px;
    color: #9ca3af;
}

.snotif-empty i {
    font-size: 24px;
    color: #10b981;
    margin-bottom: 6px;
}

.snotif-card {
    display: flex;
    gap: 10px;
    padding: 10px;
    border-radius: 8px;
    background: #f9fafb;
    margin-bottom: 8px;
    border: 1px solid #f3f4f6;
}

.snotif-card.interview { border-left: 4px solid #3b82f6; }
.snotif-card.attendance { border-left: 4px solid #ef4444; background: #fef2f2; }
.snotif-card.program { border-left: 4px solid #8b5cf6; }

.snotif-icon {
    font-size: 16px;
    color: #4f46e5;
    margin-top: 2px;
}

.snotif-card.attendance .snotif-icon { color: #ef4444; }

.snotif-content {
    flex: 1;
}

.snotif-msg {
    font-size: 12px;
    font-weight: 500;
    color: #1f2937;
    line-height: 1.4;
    margin-bottom: 4px;
}

.snotif-meta {
    font-size: 10px;
    color: #6b7280;
    margin-bottom: 6px;
}

.snotif-actions {
    display: flex;
    gap: 6px;
}

.sbtn {
    border: none;
    border-radius: 6px;
    padding: 3px 6px;
    font-size: 10px;
    font-weight: 600;
    cursor: pointer;
}

.sbtn-dismiss {
    background: #e5e7eb;
    color: #374151;
}

.sbtn-dismiss:hover {
    background: #d1d5db;
}



.trainer-id-card span {

  display: block;

  color: #77879a;

  font-size: 10px;

  font-weight: 900;

  letter-spacing: 1px;

}


.trainer-id-card strong {

  display: block;

  margin-top: 5px;

  color: #673cff;

  font-size: 14px;

  font-weight: 900;

}


/* ==================== KPI ==================== */

.trainer-kpi-grid {

  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 15px;

  margin-bottom: 18px;

}


.trainer-kpi-card {

  min-width: 0;

  min-height: 125px;

  position: relative;

  padding: 18px;

  display: flex;

  align-items: center;

  gap: 12px;

  border-radius: 14px;

  text-decoration: none !important;

  box-shadow:
    0 5px 15px rgba(31, 45, 61, 0.045);

  transition:
    transform .18s ease,
    box-shadow .18s ease;

}


.trainer-kpi-card:hover {

  transform: translateY(-2px);

  box-shadow:
    0 8px 19px rgba(31, 45, 61, 0.08);

}


.trainer-kpi-card.students-card {

  background: #f5f0ff;

  border: 1px solid #d9ccff;

}


.trainer-kpi-card.sessions-card {

  background: #edf7ff;

  border: 1px solid #c9e2f7;

}


.trainer-kpi-card.attendance-card {

  background: #eaf9f6;

  border: 1px solid #c5e8e0;

}


.trainer-kpi-card.attention-card {

  background: #fff5e8;

  border: 1px solid #f1d9b7;

}


.trainer-kpi-card.students-card
.trainer-kpi-icon {

  background: #e7ddff;

  color: #673cff;

}


.trainer-kpi-card.sessions-card
.trainer-kpi-icon {

  background: #d9edff;

  color: #1474b8;

}


.trainer-kpi-card.attendance-card
.trainer-kpi-icon {

  background: #d2f1eb;

  color: #087e71;

}


.trainer-kpi-card.attention-card
.trainer-kpi-icon {

  background: #ffe5c4;

  color: #bd6b0b;

}


.trainer-kpi-icon {

  width: 48px;

  height: 48px;

  flex: 0 0 48px;

  border-radius: 12px;

  display: flex;

  align-items: center;

  justify-content: center;

  font-size: 21px;

}


.trainer-kpi-content {

  min-width: 0;

  flex: 1;

}


.trainer-kpi-content span {

  font-size: 10px;

  font-weight: 900;

  letter-spacing: .75px;

}


.trainer-kpi-content strong {

  display: block;

  margin-top: 5px;

  color: #172a33;

  font-size: 28px;

  line-height: 1;

  font-weight: 900;

}


.trainer-kpi-content small {

  display: block;

  margin-top: 6px;

  color: #718194;

  font-size: 10px;

  font-weight: 600;

}


.kpi-arrow {

  color: #7a8795;

  font-size: 12px;

  align-self: flex-start;

  margin-top: 3px;

}


/* ==================== SECONDARY KPI ==================== */

.trainer-secondary-kpi-grid {

  display: grid;

  grid-template-columns:
    repeat(4, minmax(0, 1fr));

  gap: 15px;

  margin-bottom: 20px;

}


.secondary-kpi-card {

  min-height: 82px;

  padding: 16px;

  display: flex;

  align-items: center;

  gap: 12px;

  border: 1px solid #dfe6ee;

  border-radius: 13px;

  box-shadow:
    0 5px 15px rgba(31, 45, 61, 0.04);

}


.secondary-icon {

  width: 42px;

  height: 42px;

  flex: 0 0 42px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 11px;

  font-size: 18px;

}


.secondary-kpi-card.purple {

  background: #f7f3ff;

  border-color: #ded4ff;

}


.secondary-kpi-card.blue {

  background: #eff8ff;

  border-color: #d1e6f8;

}


.secondary-kpi-card.green {

  background: #edf9f4;

  border-color: #cbe9da;

}


.secondary-kpi-card.orange {

  background: #fff6ea;

  border-color: #f0ddc0;

}


.secondary-kpi-card.purple
.secondary-icon {

  background: #e9e0ff;

  color: #673cff;

}


.secondary-kpi-card.blue
.secondary-icon {

  background: #dcedff;

  color: #1474b8;

}


.secondary-kpi-card.green
.secondary-icon {

  background: #d9f2e5;

  color: #158057;

}


.secondary-kpi-card.orange
.secondary-icon {

  background: #ffe7c7;

  color: #bd6b0b;

}


.secondary-kpi-card span {

  font-size: 10px;

  font-weight: 900;

  letter-spacing: .6px;

}


.secondary-kpi-card strong {

  display: block;

  margin-top: 4px;

  color: #172a33;

  font-size: 24px;

  font-weight: 900;

}


/* ==================== PANELS ==================== */

.trainer-panel {

  margin-bottom: 20px;

  padding: 21px;

  background: #ffffff;

  border: 1px solid #dfe6ee;

  border-radius: 15px;

  box-shadow:
    0 5px 16px rgba(31, 45, 61, 0.04);

}


.trainer-panel-heading {

  display: flex;

  align-items: flex-start;

  justify-content: space-between;

  gap: 15px;

  margin-bottom: 19px;

}


.trainer-panel-heading.compact {

  margin-bottom: 14px;

}


.trainer-panel-heading h2 {

  margin: 5px 0 0;

  color: #172a33;

  font-size: 21px;

  font-weight: 900;

}


.trainer-panel-heading p {

  margin: 5px 0 0;

  color: #65768a;

  font-size: 12px;

}


.panel-action {

  color: #673cff;

  font-size: 11px;

  font-weight: 900;

  text-decoration: none !important;

  white-space: nowrap;

}


/* ==================== PROGRAMS ==================== */

.program-grid {

  display: grid;

  grid-template-columns:
    repeat(3, minmax(0, 1fr));

  gap: 18px;

}


.program-card {

  min-width: 0;

  min-height: 315px;

  position: relative;

  padding: 21px 20px 17px;

  overflow: hidden;

  border-radius: 15px;

  background: #ffffff;

  text-decoration: none !important;

  transition:
    transform .18s ease,
    box-shadow .18s ease;

}


.program-card:hover {

  transform: translateY(-3px);

  box-shadow:
    0 9px 20px rgba(31,45,61,.08);

}


.program-card:before {

  content: "";

  position: absolute;

  top: 0;
  left: 0;

  width: 100%;
  height: 3px;

}


.program-card:nth-child(3n + 1) {

  background: #faf8ff;

  border: 1px solid #d9cdf7;

}


.program-card:nth-child(3n + 1):before {

  background: #7044ee;

}


.program-card:nth-child(3n + 1)
.program-icon {

  background: #e7ddff;

  color: #6336db;

}


.program-card:nth-child(3n + 1)
.program-id,
.program-card:nth-child(3n + 1)
.program-progress-fill {

  color: #6336db;

}


.program-card:nth-child(3n + 2) {

  background: #f7fbff;

  border: 1px solid #cbdff1;

}


.program-card:nth-child(3n + 2):before {

  background: #2486d8;

}


.program-card:nth-child(3n + 2)
.program-icon {

  background: #dceeff;

  color: #146eb6;

}


.program-card:nth-child(3n + 2)
.program-id {

  color: #146eb6;

}


.program-card:nth-child(3n + 2)
.program-progress-fill {

  background: #2486d8;

}


.program-card:nth-child(3n) {

  background: #f6fcfb;

  border: 1px solid #c4e5df;

}


.program-card:nth-child(3n):before {

  background: #18a394;

}


.program-card:nth-child(3n)
.program-icon {

  background: #d8f2ee;

  color: #087d71;

}


.program-card:nth-child(3n)
.program-id {

  color: #087d71;

}


.program-card:nth-child(3n)
.program-progress-fill {

  background: #18a394;

}


.program-card-top {

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 10px;

}


.program-icon {

  width: 47px;

  height: 47px;

  display: flex;

  align-items: center;

  justify-content: center;

  border-radius: 12px;

  font-size: 20px;

}


.program-status {

  padding: 6px 11px;

  border-radius: 20px;

  font-size: 10px;

  font-weight: 900;

  background: #eef2f6;

  color: #526476;

}


.program-card h3 {

  margin: 18px 0 5px;

  color: #1b3038;

  font-size: 20px;

  line-height: 1.28;

  font-weight: 900;

}


.program-id {

  display: block;

  color: #6336db;

  font-size: 12px;

  font-weight: 900;

}


.program-info {

  margin-top: 18px;

  display: grid;

  grid-template-columns: 1fr;

  gap: 9px;

  font-size: 11px;

  color: #526476;

  font-weight: 700;

}


.program-info > div {

  display: flex;

  align-items: center;

  gap: 8px;

}


.program-info i {

  width: 17px;

  text-align: center;

  color: #673cff;

}


.program-progress-block {

  margin-top: 18px;

}


.program-progress-block > div:first-child {

  display: flex;

  justify-content: space-between;

  align-items: center;

}


.program-progress-block span {

  color: #65768a;

  font-size: 10px;

  font-weight: 800;

}


.program-progress-block strong {

  color: #172a33;

  font-size: 12px;

  font-weight: 900;

}


.program-progress-track {

  margin-top: 7px;

  height: 7px;

  border-radius: 7px;

  background: #e8edf2;

  overflow: hidden;

}


.program-progress-fill {

  height: 100%;

  border-radius: 7px;

  background: #7044ee;

}


.program-footer {

  margin-top: 18px;

  padding-top: 12px;

  border-top: 1px solid rgba(117,134,150,.18);

  display: flex;

  justify-content: space-between;

  gap: 10px;

  font-size: 10px;

  color: #6c7b8b;

  font-weight: 800;

}


/* ==================== TWO COLUMN ==================== */

.trainer-content-grid {

  display: grid;

  grid-template-columns:
    minmax(0, 1fr)
    minmax(0, 1fr);

  gap: 20px;

}


/* ==================== INTERVIEWS ==================== */

.interview-mini-list {

  display: flex;

  flex-direction: column;

}


.interview-mini-row {

  min-height: 74px;

  padding: 11px 0;

  display: flex;

  align-items: center;

  gap: 11px;

  border-bottom: 1px solid #edf1f5;

}


.interview-mini-row:last-child {

  border-bottom: 0;

}


.interview-mini-icon {

  width: 40px;

  height: 40px;

  flex: 0 0 40px;

  border-radius: 11px;

  display: flex;

  align-items: center;

  justify-content: center;

  background: #e8f3ff;

  color: #1f70b5;

  font-size: 16px;

}


.interview-mini-info {

  min-width: 0;

  flex: 1;

}


.interview-mini-info strong {

  display: block;

  color: #233744;

  font-size: 12px;

  font-weight: 900;

}


.interview-mini-info span {

  margin-top: 4px;

  font-size: 10px;

  color: #718194;

  font-weight: 700;

}


.trainer-status,
.student-status {

  flex: 0 0 auto;

  padding: 6px 9px;

  border-radius: 15px;

  font-size: 9px;

  font-weight: 900;

  border: 1px solid transparent;

}


.status-completed {

  background: #e7f8ee;

  color: #14855b;

  border-color: #c0e8d2;

}


.status-scheduled {

  background: #e9f2ff;

  color: #1e68b6;

  border-color: #c8def6;

}


.status-in-progress {

  background: #fff4db;

  color: #aa6400;

  border-color: #f3d28c;

}


.status-default {

  background: #eef2f6;

  color: #526476;

  border-color: #d7e0e8;

}


/* ==================== INTELLIGENCE ==================== */

.intelligence-panel {

  background: #fcfdff;

}


.student-readiness-list {

  display: flex;

  flex-direction: column;

}


.readiness-item {

  display: grid;

  grid-template-columns:
    minmax(150px,1.2fr)
    minmax(130px,1fr)
    auto
    minmax(130px,.9fr);

  gap: 13px;

  align-items: center;

  padding: 11px 0;

  border-bottom: 1px solid #edf1f5;

}


.readiness-item:last-child {

  border-bottom: 0;

}


.student-table-person {

  display: flex;

  align-items: center;

  gap: 9px;

  min-width: 0;

}


.student-table-avatar {

  width: 34px;

  height: 34px;

  border-radius: 9px;

  font-size: 10px;

  flex: 0 0 34px;

}


.student-table-person strong {

  display: block;

  color: #263b49;

  font-size: 11px;

  font-weight: 900;

  white-space: nowrap;

  overflow: hidden;

  text-overflow: ellipsis;

}


.student-table-person small {

  display: block;

  margin-top: 2px;

  color: #718194;

  font-size: 9px;

}


.readiness-main > div:first-child {

  display: flex;

  justify-content: space-between;

  align-items: center;

}


.readiness-main span {

  font-size: 9px;

  font-weight: 800;

}


.readiness-main strong {

  color: #172a33;

  font-size: 11px;

  font-weight: 900;

}


.table-progress {

  margin-top: 5px;

  height: 6px;

  background: #e8edf2;

  border-radius: 6px;

  overflow: hidden;

}


.table-progress-fill {

  height: 100%;

  background: #673cff;

  border-radius: 6px;

}


.risk-high {

  background: #ffebed;

  color: #b52c37;

  border-color: #ffc0c5;

}


.risk-medium {

  background: #fff3d9;

  color: #a45c00;

  border-color: #ffd18a;

}


.risk-low {

  background: #e5faef;

  color: #087d4b;

  border-color: #9ae1bb;

}


.skill-gap {

  min-width: 0;

  color: #607184;

  font-size: 10px;

  line-height: 1.4;

  font-weight: 700;

}


/* ==================== FOLLOW UP ==================== */

.followup-grid {

  display: grid;

  grid-template-columns:
    repeat(2,minmax(0,1fr));

  gap: 12px;

}


.followup-card {

  min-height: 92px;

  padding: 13px;

  display: grid;

  grid-template-columns:
    36px
    1fr
    auto;

  align-items: center;

  gap: 10px;

  border-radius: 12px;

}


.followup-card.danger {

  background: #fff4f4;

  border: 1px solid #f0cccc;

}


.followup-card.warning {

  background: #fff9ed;

  border: 1px solid #f0ddb1;

}


.followup-icon {

  width: 36px;

  height: 36px;

  border-radius: 10px;

  font-size: 15px;

}


.followup-card.danger
.followup-icon {

  background: #ffe1e1;

  color: #bd303a;

}


.followup-card.warning
.followup-icon {

  background: #ffecbf;

  color: #aa6500;

}


.followup-card strong {

  display: block;

  color: #263b49;

  font-size: 11px;

  font-weight: 900;

}


.followup-card span {

  margin-top: 2px;

  font-size: 9px;

  font-weight: 700;

}


.followup-card p {

  margin: 4px 0 0;

  color: #69798a;

  font-size: 9px;

  line-height: 1.4;

  font-weight: 650;

}


.followup-card a {

  color: #673cff;

  font-size: 10px;

  font-weight: 900;

  text-decoration: none !important;

  white-space: nowrap;

}


.followup-empty {

  grid-column: 1 / -1;

  min-height: 90px;

  padding: 16px;

  display: flex;

  align-items: center;

  gap: 12px;

  border: 1px dashed #cfd9e3;

  border-radius: 12px;

  background: #f8fafc;

}


.followup-empty > i {

  color: #15905f;

  font-size: 20px;

}


.followup-empty strong {

  color: #263b49;

  font-size: 12px;

}


.followup-empty p {

  margin: 4px 0 0;

  color: #718194;

  font-size: 10px;

}


/* ==================== TPO ==================== */

.trainer-coordination-strip {

  margin-top: 20px;

  padding: 17px 19px;

  display: flex;

  align-items: center;

  gap: 14px;

  background:
    linear-gradient(
      135deg,
      #f7f4ff 0%,
      #eef7ff 100%
    );

  border: 1px solid #d8d4ef;

  border-radius: 15px;

}


.coordination-icon {

  width: 48px;

  height: 48px;

  flex: 0 0 48px;

  border-radius: 12px;

  background: #e7ddff;

  color: #673cff;

  font-size: 20px;

}


.coordination-copy {

  min-width: 0;

  flex: 1;

}


.coordination-copy > span {

  color: #673cff;

}


.coordination-copy strong {

  display: block;

  margin-top: 4px;

  color: #1f3340;

  font-size: 15px;

  font-weight: 900;

}


.coordination-copy p {

  margin: 4px 0 0;

  color: #637386;

  font-size: 10px;

  line-height: 1.5;

}


.coordination-button {

  flex: 0 0 auto;

  padding: 10px 13px;

  border-radius: 9px;

  background: #673cff;

  color: #ffffff;

  text-decoration: none !important;

  font-size: 10px;

  font-weight: 900;

  box-shadow:
    0 5px 13px rgba(103,60,255,.16);

}


.coordination-button:hover {

  background: #5730d8;

}


/* ==================== EMPTY / LOADING ==================== */

.trainer-empty {

  min-height: 90px;

  padding: 18px;

  display: flex;

  flex-direction: column;

  align-items: center;

  justify-content: center;

  color: #7b8998;

  text-align: center;

}


.trainer-empty i {

  color: #b0bac4;

  font-size: 24px;

}


.trainer-empty p {

  margin: 7px 0 0;

  font-size: 11px;

  font-weight: 700;

}


.trainer-dashboard-footer {

  display: flex;

  justify-content: space-between;

  align-items: center;

  padding: 2px 2px 8px;

  color: #7a8898;

  font-size: 10px;

  font-weight: 700;

}


.trainer-dashboard-loading {

  min-height: 100vh;

  width: 100vw;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 10px;

  color: #66788a;

  font-size: 14px;

  font-weight: 700;

}


.trainer-dashboard-loading i {

  color: #673cff;

}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width:1200px) {

  .trainer-kpi-grid,
  .trainer-secondary-kpi-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr));

  }


  .program-grid {

    grid-template-columns:
      repeat(2,minmax(0,1fr));

  }

}


@media (max-width:950px) {

  .campus360-trainer-sidebar {

    width: 215px !important;

    min-width: 215px !important;

    max-width: 215px !important;

    background:
      linear-gradient(
        180deg,
        #130d2f 0%,
        #160d38 48%,
        #100a29 100%
      ) !important;

    border-right: 1px solid #2d2157 !important;

  }


  .campus360-trainer-main {

    left: 215px !important;

    width: calc(100vw - 215px) !important;

    max-width: calc(100vw - 215px) !important;

  }


  .trainer-content-grid {

    grid-template-columns: 1fr;

  }


  .readiness-item {

    grid-template-columns:
      1fr
      1fr
      auto;

  }


  .skill-gap {

    grid-column: 1 / -1;

  }

}


@media (max-width:750px) {

  .campus360-trainer-sidebar {

    position: fixed !important;

    width: 250px !important;

    min-width: 250px !important;

    max-width: 250px !important;

    transform: translateX(-100%);

    transition:
      transform .25s ease;

    background:
      linear-gradient(
        180deg,
        #130d2f 0%,
        #160d38 48%,
        #100a29 100%
      ) !important;

    border-right: 1px solid #2d2157 !important;

  }


  .campus360-trainer-main {

    left: 0 !important;

    width: 100vw !important;

    max-width: 100vw !important;

  }


  .trainer-topbar {

    padding: 0 16px;

  }


  .trainer-dashboard-content {

    padding: 22px 16px 40px;

  }


  .trainer-welcome {

    align-items: flex-start;

    flex-direction: column;

  }


  .trainer-kpi-grid,
  .trainer-secondary-kpi-grid,
  .program-grid,
  .followup-grid {

    grid-template-columns: 1fr;

  }


  .trainer-coordination-strip {

    align-items: flex-start;

    flex-wrap: wrap;

  }


  .coordination-button {

    margin-left: 62px;

  }


  .trainer-dashboard-footer {

    gap: 8px;

    flex-direction: column;

    align-items: flex-start;

  }

}


@media (max-width:560px) {

  .trainer-top-profile > div:last-child {

    display: none;

  }


  .trainer-top-profile {

    padding-left: 4px;

  }


  .trainer-topbar-title {

    font-size: 14px;

  }


  .trainer-kpi-grid,
  .trainer-secondary-kpi-grid {

    grid-template-columns: 1fr;

  }

}

sp_widget.script:
(function() {
  data.loaded = false;
  data.aiWidget = $sp.getWidget('c4ae634574e703107f4410c9fee0cde5');

  /* ============================================================
     CURRENT TRAINER

     URL example:
     ?id=campus360_trainer_dashboard&trainer=TR001

     The trainer parameter controls which trainer's
     dashboard data is displayed.
     ============================================================ */

  var requestedTrainerId = ($sp.getParameter('trainer') || '').trim();

  var trainerGR = new GlideRecord(
    'x_snc_campus360_trainer_master'
  );

  if (requestedTrainerId) {

    trainerGR.addQuery(
      'trainer_id',
      requestedTrainerId
    );

    trainerGR.setLimit(1);
    trainerGR.query();

  } else {

    /* No trainer parameter:
       load the first active trainer */

    trainerGR.addQuery(
      'status',
      'Active'
    );

    trainerGR.orderBy(
      'trainer_id'
    );

    trainerGR.setLimit(1);
    trainerGR.query();
  }


  /* ============================================================
     NO TRAINER FOUND
     ============================================================ */

  if (!trainerGR.next()) {

    data.loaded = true;

    data.error =
      'No trainer record found in Trainer Master.';

    return;
  }


  /* ============================================================
     TRAINER INFORMATION
     ============================================================ */

  var trainerSysId =
    trainerGR.getUniqueValue();

  var trainerId =
    trainerGR.getValue(
      'trainer_id'
    ) || '';

  var trainerName =
    trainerGR.getValue(
      'trainer_name'
    ) || '';


  data.trainer = {

    sys_id:
      trainerSysId,

    id:
      trainerId,

    name:
      trainerName,

    email:
      trainerGR.getValue(
        'email'
      ) || '',

    expertise:
      trainerGR.getValue(
        'expertise'
      ) || '',

    experience:
      trainerGR.getValue(
        'experience'
      ) || '0',

    rating:
      trainerGR.getValue(
        'rating'
      ) || '0',

    status:
      trainerGR.getValue(
        'status'
      ) || '',

    totalInterviews:
      parseInt(
        trainerGR.getValue(
          'total_interviews'
        ),
        10
      ) || 0,

    initials:
      getInitials(
        trainerName
      )
  };


  /* ============================================================
     TRAINING PROGRAMS

     Table:
     x_snc_campus360_training_program

     Trainer field:
     trainer
     ============================================================ */

  data.programs = [];

  var studentIds = {};

  var totalAssessment = 0;
  var assessmentCount = 0;


  var programGR =
    new GlideRecord(
      'x_snc_campus360_training_program'
    );


  programGR.addQuery(
    'trainer',
    trainerSysId
  );

  programGR.orderBy(
    'start_date'
  );

  programGR.query();


  while (programGR.next()) {

    var programSysId =
      programGR.getUniqueValue();


    var enrollmentStats =
      getEnrollmentStats(
        programSysId
      );


    var assignmentCount =
      getAssignmentCount(
        programSysId
      );


    /* Add enrolled students to trainer student pool */

    for (
      var sid in enrollmentStats.students
    ) {

      if (
        enrollmentStats.students.hasOwnProperty(
          sid
        )
      ) {

        studentIds[sid] = true;
      }
    }


    totalAssessment +=
      enrollmentStats.totalAssessment;

    assessmentCount +=
      enrollmentStats.assessmentCount;


    data.programs.push({

      sys_id:
        programSysId,

      id:
        programGR.getValue(
          'training_id'
        ) || '',

      name:
        programGR.getValue(
          'training_name'
        ) || '',

      skillArea:
        programGR.getValue(
          'skill_area'
        ) || '',

      batch:
        programGR.getValue(
          'batch'
        ) || '',

      startDate:
        formatDate(
          programGR.getValue(
            'start_date'
          )
        ),

      endDate:
        formatDate(
          programGR.getValue(
            'end_date'
          )
        ),

      startValue:
        programGR.getValue(
          'start_date'
        ) || '',

      endValue:
        programGR.getValue(
          'end_date'
        ) || '',

      capacity:
        parseInt(
          programGR.getValue(
            'capacity'
          ),
          10
        ) || 0,

      status:
        programGR.getValue(
          'status'
        ) || '',

      students:
        enrollmentStats.studentCount,

      progress:
        enrollmentStats.progressCount > 0
          ? Math.round(
              enrollmentStats.totalProgress /
              enrollmentStats.progressCount
            )
          : 0,

      assignments:
        assignmentCount
    });
  }


  /* ============================================================
     TRAINING ATTENDANCE

     Separate from Mock Interview attendance.
     ============================================================ */

  var attendanceStats =
    getTrainingAttendance(
      trainerSysId
    );


  /* ============================================================
     MOCK INTERVIEW REQUESTS

     Table:
     x_snc_campus360_mock_interview_request_trainer
     ============================================================ */

  var requestData =
    getInterviewRequests(
      trainerSysId
    );


  data.interviewRequests =
    requestData.items;


  /* ============================================================
     TRAINER INTERVIEW AVAILABILITY

     Table:
     x_snc_campus360_trainer_interview_availability
     ============================================================ */

  data.availableSlotsList = [];


  var availableSlotCount =
    getAvailableSlotCount(
      trainerSysId,
      data.availableSlotsList
    );


  /* ============================================================
     MOCK INTERVIEWS

     Table:
     x_snc_campus360_mock_interview
     ============================================================ */

  data.interviews = [];


  var interviewGR =
    new GlideRecord(
      'x_snc_campus360_mock_interview'
    );


  interviewGR.addQuery(
    'trainer',
    trainerSysId
  );

  interviewGR.orderByDesc(
    'interview_date'
  );

  interviewGR.query();


  var interviewCount = 0;

  var pendingFeedbackList = [];


  while (interviewGR.next()) {

    interviewCount++;


    var interviewStudentSysId =
      interviewGR.getValue(
        'student'
      );


    var interviewStudent =
      getStudentName(
        interviewStudentSysId
      ) ||
      interviewGR.getDisplayValue(
        'student'
      ) ||
      'Student';


    var interviewStatus =
      interviewGR.getValue(
        'interview_status'
      ) || '';


    var interviewSysId =
      interviewGR.getUniqueValue();


    var interviewObj = {

      sys_id:
        interviewSysId,

      student:
        interviewStudent,

      date:
        formatDate(
          interviewGR.getValue(
            'interview_date'
          )
        ),

      startTime:
        interviewGR.getValue(
          'start_time'
        ) || '',

      endTime:
        interviewGR.getValue(
          'end_time'
        ) || '',

      status:
        interviewStatus,

      attendance:
        interviewGR.getValue(
          'attendance_status'
        ) || '',

      type:
        interviewGR.getValue(
          'interview_type'
        ) || ''
    };


    data.interviews.push(
      interviewObj
    );


    /* Completed interview with no feedback */

    if (
      interviewStatus == 'Completed' &&
      !hasInterviewFeedback(
        interviewSysId
      )
    ) {

      pendingFeedbackList.push({

        sys_id:
          interviewSysId,

        student:
          interviewStudent,

        date:
          interviewObj.date,

        type:
          interviewObj.type
      });
    }
  }


  /* ============================================================
     PLACEMENT INTELLIGENCE

     Only show intelligence for students connected
     to this trainer through Training Enrollment.
     ============================================================ */

  data.performance = [];

  data.attentionStudents = [];


  var intelligenceGR =
    new GlideRecord(
      'x_snc_campus360_placement_intelligence'
    );


  intelligenceGR.query();


  while (
    intelligenceGR.next()
  ) {

    var intelligenceStudent =
      intelligenceGR.getValue(
        'student'
      );


    if (
      !intelligenceStudent ||
      !studentIds[
        intelligenceStudent
      ]
    ) {

      continue;
    }


    var studentInfo =
      getStudentInfo(
        intelligenceStudent
      );


    var risk =
      intelligenceGR.getValue(
        'risk_level'
      ) || '';


    var readiness =
      getNumber(
        intelligenceGR.getValue(
          'readiness_score'
        )
      );


    var skillGap =
      intelligenceGR.getValue(
        'primary_skill_gap'
      ) || '';


    var performanceObj = {

      id:
        studentInfo.id,

      name:
        studentInfo.name ||
        intelligenceGR.getDisplayValue(
          'student'
        ) ||
        'Student',

      initials:
        getInitials(
          studentInfo.name ||
          'Student'
        ),

      readiness:
        readiness,

      risk:
        risk,

      skillGap:
        skillGap
    };


    data.performance.push(
      performanceObj
    );


    /* Students marked High risk */

    if (
      risk == 'High'
    ) {

      data.attentionStudents.push(
        performanceObj
      );
    }
  }


  /* ============================================================
     DASHBOARD METRICS
     ============================================================ */

  data.metrics = {

    trainingPrograms:
      data.programs.length,

    students:
      countKeys(
        studentIds
      ),

    programsToday:
      countProgramsToday(
        data.programs
      ),

    attendance:
      attendanceStats.total > 0
        ? Math.round(
            (
              attendanceStats.present /
              attendanceStats.total
            ) * 100
          )
        : 0,

    averageAssessment:
      assessmentCount > 0
        ? Math.round(
            totalAssessment /
            assessmentCount
          )
        : 0,

    interviews:
      interviewCount,

    interviewRequests:
      requestData.pendingCount,

    availableSlots:
      availableSlotCount,

    attentionStudents:
      data.attentionStudents.length,

    pendingFeedback:
      pendingFeedbackList.length
  };


  /* ============================================================
     ADDITIONAL DASHBOARD DATA
     ============================================================ */

  data.pendingFeedbackList =
    pendingFeedbackList;


  data.assignmentSummary =
    getAssignmentSummary(
      trainerSysId
    );


  /* ============================================================
     FINISHED
     ============================================================ */

  data.loaded = true;


  /* ============================================================
     HELPERS
     ============================================================ */


  /* ------------------------------------------------------------
     TRAINING ENROLLMENT STATISTICS
     ------------------------------------------------------------ */

  function getEnrollmentStats(
    programSysId
  ) {

    var result = {

      students: {},

      studentCount: 0,

      totalProgress: 0,

      progressCount: 0,

      totalAssessment: 0,

      assessmentCount: 0
    };


    var gr =
      new GlideRecord(
        'x_snc_campus360_training_enrollment'
      );


    gr.addQuery(
      'training_program',
      programSysId
    );


    gr.query();


    while (
      gr.next()
    ) {

      var sid =
        gr.getValue(
          'student'
        );


      if (
        sid &&
        !result.students[sid]
      ) {

        result.students[sid] = true;

        result.studentCount++;
      }


      var progress =
        parseFloat(
          gr.getValue(
            'progress_percentage'
          )
        );


      if (
        !isNaN(
          progress
        )
      ) {

        result.totalProgress +=
          progress;

        result.progressCount++;
      }


      var assessment =
        parseFloat(
          gr.getValue(
            'assessment_score'
          )
        );


      if (
        !isNaN(
          assessment
        )
      ) {

        result.totalAssessment +=
          assessment;

        result.assessmentCount++;
      }
    }


    return result;
  }


  /* ------------------------------------------------------------
     TRAINING ATTENDANCE
     ------------------------------------------------------------ */

  function getTrainingAttendance(
    trainerSysId
  ) {

    var out = {

      total: 0,

      present: 0
    };


    var gr =
      new GlideRecord(
        'x_snc_campus360_training_attendance'
      );


    if (
      !gr.isValidField(
        'training_program'
      )
    ) {

      return out;
    }


    gr.addQuery(
      'training_program.trainer',
      trainerSysId
    );


    gr.query();


    while (
      gr.next()
    ) {

      var value = '';


      if (
        gr.isValidField(
          'attendance_status'
        )
      ) {

        value =
          gr.getValue(
            'attendance_status'
          );

      } else if (
        gr.isValidField(
          'status'
        )
      ) {

        value =
          gr.getValue(
            'status'
          );

      } else if (
        gr.isValidField(
          'attendance'
        )
      ) {

        value =
          gr.getValue(
            'attendance'
          );
      }


      if (
        value === ''
      ) {

        continue;
      }


      out.total++;


      if (
        String(
          value
        ).toLowerCase() ==
        'present'
      ) {

        out.present++;
      }
    }


    return out;
  }


  /* ------------------------------------------------------------
     ASSIGNMENT COUNT
     ------------------------------------------------------------ */

  function getAssignmentCount(
    programSysId
  ) {

    var gr =
      new GlideRecord(
        'x_snc_campus360_assignment'
      );


    if (
      !gr.isValidField(
        'training_program'
      )
    ) {

      return 0;
    }


    gr.addQuery(
      'training_program',
      programSysId
    );


    gr.query();


    var count = 0;


    while (
      gr.next()
    ) {

      count++;
    }


    return count;
  }


  /* ------------------------------------------------------------
     ASSIGNMENT SUMMARY
     ------------------------------------------------------------ */

  function getAssignmentSummary(
    trainerSysId
  ) {

    var list = [];


    var gr =
      new GlideRecord(
        'x_snc_campus360_assignment'
      );


    if (
      !gr.isValidField(
        'training_program'
      )
    ) {

      return list;
    }


    gr.addQuery(
      'training_program.trainer',
      trainerSysId
    );


    if (
      gr.isValidField(
        'sys_created_on'
      )
    ) {

      gr.orderByDesc(
        'sys_created_on'
      );
    }


    gr.setLimit(5);

    gr.query();


    while (
      gr.next()
    ) {

      var name =
        firstValue(
          gr,
          [
            'assignment_name',
            'name',
            'title'
          ]
        ) ||
        gr.getDisplayValue();


      list.push({

        sys_id:
          gr.getUniqueValue(),

        name:
          name,

        dueDate:
          firstDisplayValue(
            gr,
            [
              'due_date',
              'deadline'
            ]
          ),

        status:
          firstValue(
            gr,
            [
              'status',
              'completion_status'
            ]
          )
      });
    }


    return list;
  }


  /* ------------------------------------------------------------
     INTERVIEW REQUESTS
     ------------------------------------------------------------ */

  function getInterviewRequests(
    trainerSysId
  ) {

    var result = {

      pendingCount: 0,

      items: []
    };


    var gr =
      new GlideRecord(
        'x_snc_campus360_mock_interview_request_trainer'
      );


    if (
      !gr.isValidField(
        'trainer'
      )
    ) {

      return result;
    }


    gr.addQuery(
      'trainer',
      trainerSysId
    );


    if (
      gr.isValidField(
        'sys_created_on'
      )
    ) {

      gr.orderByDesc(
        'sys_created_on'
      );
    }


    gr.setLimit(20);

    gr.query();


    while (
      gr.next()
    ) {

      var status =
        firstValue(
          gr,
          [
            'status',
            'request_status'
          ]
        );


      var normalized =
        String(
          status || ''
        ).toLowerCase();


      if (
        normalized ==
          'requested' ||
        normalized ==
          'pending'
      ) {

        result.pendingCount++;
      }


      result.items.push({

        sys_id:
          gr.getUniqueValue(),

        status:
          status || '',

        student:
          getRequestStudentName(
            gr
          ),

        date:
          getRequestDate(
            gr
          )
      });
    }


    return result;
  }


  /* ------------------------------------------------------------
     AVAILABLE INTERVIEW SLOTS
     ------------------------------------------------------------ */

  function getAvailableSlotCount(
    trainerSysId,
    list
  ) {

    var count = 0;


    var gr =
      new GlideRecord(
        'x_snc_campus360_trainer_interview_availability'
      );


    if (
      !gr.isValidField(
        'trainer'
      )
    ) {

      return 0;
    }


    gr.addQuery(
      'trainer',
      trainerSysId
    );


    if (
      gr.isValidField(
        'sys_created_on'
      )
    ) {

      gr.orderBy(
        'sys_created_on'
      );
    }


    gr.query();


    while (
      gr.next()
    ) {

      var status =
        firstValue(
          gr,
          [
            'status',
            'slot_status',
            'availability_status'
          ]
        );


      if (
        status &&
        String(
          status
        ).toLowerCase() !=
        'available'
      ) {

        continue;
      }


      count++;


      if (
        list.length < 5
      ) {

        list.push({

          date:
            firstDisplayValue(
              gr,
              [
                'available_date',
                'slot_date',
                'date',
                'interview_date'
              ]
            ),

          start:
            firstValue(
              gr,
              [
                'start_time',
                'available_start_time'
              ]
            ),

          end:
            firstValue(
              gr,
              [
                'end_time',
                'available_end_time'
              ]
            ),

          status:
            status ||
            'Available'
        });
      }
    }


    return count;
  }


  /* ------------------------------------------------------------
     CHECK IF INTERVIEW HAS FEEDBACK
     ------------------------------------------------------------ */

  function hasInterviewFeedback(
    interviewSysId
  ) {

    var gr =
      new GlideRecord(
        'x_snc_campus360_interview_feedback'
      );


    if (
      !gr.isValidField(
        'interview'
      )
    ) {

      return false;
    }


    gr.addQuery(
      'interview',
      interviewSysId
    );


    gr.setLimit(1);

    gr.query();


    return gr.hasNext();
  }


  /* ------------------------------------------------------------
     REQUEST STUDENT
     ------------------------------------------------------------ */

  function getRequestStudentName(
    requestGR
  ) {

    var requestSysId =
      firstValue(
        requestGR,
        [
          'mock_interview_slot_request',
          'slot_request',
          'request'
        ]
      );


    if (
      requestSysId
    ) {

      var req =
        new GlideRecord(
          'x_snc_campus360_mock_interview_slot_request'
        );


      if (
        req.get(
          requestSysId
        ) &&
        req.isValidField(
          'student'
        )
      ) {

        return (
          getStudentName(
            req.getValue(
              'student'
            )
          ) ||
          req.getDisplayValue(
            'student'
          ) ||
          'Student'
        );
      }
    }


    if (
      requestGR.isValidField(
        'student'
      )
    ) {

      return (
        getStudentName(
          requestGR.getValue(
            'student'
          )
        ) ||
        requestGR.getDisplayValue(
          'student'
        ) ||
        'Student'
      );
    }


    return 'Student';
  }


  /* ------------------------------------------------------------
     REQUEST DATE
     ------------------------------------------------------------ */

  function getRequestDate(
    requestGR
  ) {

    var requestSysId =
      firstValue(
        requestGR,
        [
          'mock_interview_slot_request',
          'slot_request',
          'request'
        ]
      );


    if (
      requestSysId
    ) {

      var req =
        new GlideRecord(
          'x_snc_campus360_mock_interview_slot_request'
        );


      if (
        req.get(
          requestSysId
        )
      ) {

        return firstDisplayValue(
          req,
          [
            'requested_date',
            'slot_date',
            'date',
            'interview_date'
          ]
        );
      }
    }


    return firstDisplayValue(
      requestGR,
      [
        'requested_date',
        'slot_date',
        'date',
        'interview_date'
      ]
    );
  }


  /* ------------------------------------------------------------
     STUDENT INFORMATION
     ------------------------------------------------------------ */

  function getStudentInfo(
    studentSysId
  ) {

    var result = {

      name: '',

      id: ''
    };


    var gr =
      new GlideRecord(
        'x_snc_campus360_student_master'
      );


    if (
      studentSysId &&
      gr.get(
        studentSysId
      )
    ) {

      result.name =
        gr.getValue(
          'student_name'
        ) || '';


      result.id =
        gr.getValue(
          'student_id'
        ) || '';
    }


    return result;
  }


  /* ------------------------------------------------------------
     STUDENT NAME
     ------------------------------------------------------------ */

  function getStudentName(
    studentSysId
  ) {

    return getStudentInfo(
      studentSysId
    ).name;
  }


  /* ------------------------------------------------------------
     PROGRAMS ACTIVE TODAY
     ------------------------------------------------------------ */

  function countProgramsToday(
    programs
  ) {

    var today =
      new GlideDate().getValue();


    var count = 0;


    for (
      var i = 0;
      i < programs.length;
      i++
    ) {

      if (
        programs[i].startValue &&
        programs[i].endValue &&
        programs[i].startValue <= today &&
        today <= programs[i].endValue
      ) {

        count++;
      }
    }


    return count;
  }


  /* ------------------------------------------------------------
     COUNT OBJECT KEYS
     ------------------------------------------------------------ */

  function countKeys(
    obj
  ) {

    var count = 0;


    for (
      var k in obj
    ) {

      if (
        obj.hasOwnProperty(k)
      ) {

        count++;
      }
    }


    return count;
  }


  /* ------------------------------------------------------------
     GET FIRST VALID FIELD VALUE
     ------------------------------------------------------------ */

  function firstValue(
    gr,
    fields
  ) {

    for (
      var i = 0;
      i < fields.length;
      i++
    ) {

      if (
        gr.isValidField(
          fields[i]
        )
      ) {

        var v =
          gr.getValue(
            fields[i]
          );


        if (
          v !== null &&
          v !== ''
        ) {

          return v;
        }
      }
    }


    return '';
  }


  /* ------------------------------------------------------------
     GET FIRST DISPLAY VALUE
     ------------------------------------------------------------ */

  function firstDisplayValue(
    gr,
    fields
  ) {

    for (
      var i = 0;
      i < fields.length;
      i++
    ) {

      if (
        gr.isValidField(
          fields[i]
        )
      ) {

        var raw =
          gr.getValue(
            fields[i]
          );


        if (
          raw !== null &&
          raw !== ''
        ) {

          return gr.getDisplayValue(
            fields[i]
          );
        }
      }
    }


    return '';
  }


  /* ------------------------------------------------------------
     DATE FORMAT
     ------------------------------------------------------------ */

  function formatDate(
    value
  ) {

    if (
      !value
    ) {

      return '';
    }


    var gd =
      new GlideDate();


    gd.setValue(
      value
    );


    return gd.getDisplayValue();
  }


  /* ------------------------------------------------------------
     NUMBER
     ------------------------------------------------------------ */

  function getNumber(
    value
  ) {

    var n =
      parseFloat(
        value
      );


    return isNaN(
      n
    )
      ? 0
      : Math.round(
          n
        );
  }


  /* ------------------------------------------------------------
     INITIALS
     ------------------------------------------------------------ */

  function getInitials(
    name
  ) {

    if (
      !name
    ) {

      return 'TR';
    }


    var parts =
      String(
        name
      )
      .trim()
      .split(
        /\s+/
      );


    if (
      parts.length == 1
    ) {

      return parts[0]
        .substring(
          0,
          2
        )
        .toUpperCase();
    }


    return (
      parts[0].charAt(0) +
      parts[
        parts.length - 1
      ].charAt(0)
    ).toUpperCase();
  }

  /* ============================================================
     TRAINER NOTIFICATIONS ENGINE
     ============================================================ */
  data.notifications = [];

  // 1. Training Program Assigned Notifications
  var trProgGR = new GlideRecord('x_snc_campus360_training_program');
  trProgGR.addQuery('trainer', trainerSysId);
  trProgGR.orderByDesc('sys_created_on');
  trProgGR.setLimit(5);
  trProgGR.query();

  while (trProgGR.next()) {
      var pName = trProgGR.getValue('training_name') || trProgGR.getValue('name') || 'Training Program';
      var pSkill = trProgGR.getValue('skill_area') || 'Core Skills';
      var pBatch = trProgGR.getValue('batch') || 'Current Batch';
      var pStart = trProgGR.getDisplayValue('start_date') || 'Upcoming';

      data.notifications.push({
          sys_id: 'tr_notif_prog_' + trProgGR.getUniqueValue(),
          type: 'program',
          title: 'Training Program Assigned: ' + pName,
          message: 'You have been assigned to lead "' + pName + '" (' + pSkill + ') for batch ' + pBatch + '. Scheduled Start: ' + pStart + '.',
          time: pStart
      });
  }

  // 2. Student Mock Interview Requests for Trainer
  var trMockGR = new GlideRecord('x_snc_campus360_mock_interview');
  trMockGR.addQuery('trainer', trainerSysId);
  trMockGR.orderByDesc('sys_created_on');
  trMockGR.setLimit(5);
  trMockGR.query();

  while (trMockGR.next()) {
      var sName = trMockGR.getDisplayValue('student') || 'Student Candidate';
      var mTopic = trMockGR.getValue('topic') || trMockGR.getValue('interview_type') || 'Technical Mock Interview';
      var mDate = trMockGR.getDisplayValue('scheduled_date') || trMockGR.getDisplayValue('sys_created_on') || 'Requested';

      data.notifications.push({
          sys_id: 'tr_notif_mock_' + trMockGR.getUniqueValue(),
          type: 'interview',
          title: 'Mock Interview Request: ' + sName,
          message: sName + ' has requested a mock interview session for ' + mTopic + '. Date: ' + mDate + '.',
          time: mDate
      });
  }

  // 3. New Placement Opportunity Published Notifications
  var trOppGR = new GlideRecord('x_snc_campus360_placement_opportunity');
  trOppGR.orderByDesc('sys_created_on');
  trOppGR.setLimit(3);
  trOppGR.query();

  while (trOppGR.next()) {
      var cName = trOppGR.getDisplayValue('company') || 'Partner Company';
      var rRole = trOppGR.getValue('job_role') || trOppGR.getValue('title') || 'Placement Drive';
      var dDeadline = trOppGR.getDisplayValue('deadline') || 'Open';

      data.notifications.push({
          sys_id: 'tr_notif_opp_' + trOppGR.getUniqueValue(),
          type: 'opportunity',
          title: 'Placement Drive Published: ' + rRole,
          message: cName + ' has published a new placement opportunity for ' + rRole + '. Application Deadline: ' + dDeadline + '.',
          time: dDeadline
      });
  }

  data.unreadCount = data.notifications.length;

})();
